/* Fresh-process executor for bounded Cycle45/46 reducer-generated MIR text. */
#include "mir.h"
#include "mir-gen.h"
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(int argc,char **argv){FILE*f;long n;char*s;MIR_context_t c;MIR_module_t m;MIR_item_t it=NULL,x;MIR_val_t a[2],r[1];int64_t v0=0,v1=0;int mem=argc==3&&!strcmp(argv[2],"--memory");if((!mem&&(argc<3||argc>4))||(mem&&argc!=3))return 2;if(!mem){v0=strtoll(argv[2],NULL,0);if(argc==4)v1=strtoll(argv[3],NULL,0);}f=fopen(argv[1],"rb");if(!f)return 3;if(fseek(f,0,SEEK_END)||(n=ftell(f))<0||fseek(f,0,SEEK_SET))return 4;s=malloc((size_t)n+1);if(!s)return 5;if(fread(s,1,(size_t)n,f)!=(size_t)n)return 6;fclose(f);s[n]=0;c=MIR_init();MIR_scan_string(c,s);free(s);for(m=DLIST_HEAD(MIR_module_t,*MIR_get_module_list(c));m;m=DLIST_NEXT(MIR_module_t,m))for(x=DLIST_HEAD(MIR_item_t,m->items);x;x=DLIST_NEXT(MIR_item_t,x))if(x->item_type==MIR_func_item&&!strcmp(MIR_item_name(c,x),"reduce_case"))it=x;if(!it)return 7;for(m=DLIST_HEAD(MIR_module_t,*MIR_get_module_list(c));m;m=DLIST_NEXT(MIR_module_t,m))MIR_load_module(c,m);MIR_gen_init(c);MIR_link(c,MIR_set_gen_interface,NULL);unsigned char buf[24];memset(buf,0xa5,sizeof buf);if(mem){buf[0]=0x80;a[0].a=buf;}else{a[0].i=v0;a[1].i=v1;}MIR_interp_arr(c,it,r,it->u.func->nargs,a);if(mem)fprintf(stderr,"dbg nargs=%u nres=%u arg0=%p result=%016" PRIx64 "\n",it->u.func->nargs,it->u.func->nres,a[0].a,r[0].u);printf("interp=%" PRId64 "\n",r[0].i);if(mem){memset(buf,0xa5,sizeof buf);buf[0]=0x80;}int64_t got;if(mem){typedef int64_t(*fn)(void*);got=((fn)MIR_gen(c,it))(buf);}else if(it->u.func->nargs==1){typedef int64_t(*fn)(int64_t);got=((fn)MIR_gen(c,it))(v0);}else{typedef int64_t(*fn)(int64_t,int64_t);got=((fn)MIR_gen(c,it))(v0,v1);}printf("jit=%" PRId64 "\n",got);if(mem){printf("memory=");for(size_t i=0;i<sizeof buf;i++)printf("%02x",buf[i]);puts("");}MIR_gen_finish(c);MIR_finish(c);return 0;}
